// Vehicle category drives the daily rental rate.
enum VehicleCategory {
    ECONOMY, // cheapest tier
    SUV,     // mid tier
    LUXURY   // premium tier
}

// Lifecycle status of a single vehicle.
enum VehicleStatus {
    AVAILABLE, // free to be reserved
    RESERVED,  // claimed but not yet picked up
    RENTED     // currently with a customer
}

// A single rentable vehicle.
class Vehicle {
    private final String vehicleId;       // unique id, e.g. ECO1
    private final VehicleCategory category; // pricing tier
    private String currentBranchId;       // branch that currently holds it
    private VehicleStatus status;         // current lifecycle state

    public Vehicle(String vehicleId, VehicleCategory category, String branchId) {
        this.vehicleId = vehicleId;       // store id
        this.category = category;         // store category
        this.currentBranchId = branchId;  // store starting branch
        this.status = VehicleStatus.AVAILABLE; // new vehicles start free
    }

    public String getVehicleId() { return vehicleId; }             // id getter
    public VehicleCategory getCategory() { return category; }      // category getter
    public String getCurrentBranchId() { return currentBranchId; } // branch getter
    public VehicleStatus getStatus() { return status; }            // status getter

    public void setStatus(VehicleStatus status) { this.status = status; } // status setter
    public void setCurrentBranchId(String branchId) { this.currentBranchId = branchId; } // branch setter

    public boolean isAvailable() { return status == VehicleStatus.AVAILABLE; } // convenience check
}

// Creates vehicles with category-prefixed ids for a branch.
class VehicleFactory {
    // count how many of each prefix already exist so ids never collide
    private final java.util.Map<String, Integer> counters = new java.util.HashMap<>();

    public java.util.List<Vehicle> createVehicles(String branchId, VehicleCategory category, int count) {
        String prefix = prefixFor(category);              // e.g. "ECO"
        java.util.List<Vehicle> created = new java.util.ArrayList<>(); // result list
        for (int i = 0; i < count; i++) {                  // create 'count' vehicles
            int n = counters.getOrDefault(prefix, 0) + 1;   // next number for this prefix
            counters.put(prefix, n);                        // remember it
            created.add(new Vehicle(prefix + n, category, branchId)); // e.g. ECO1
        }
        return created; // hand back the new vehicles
    }

    private String prefixFor(VehicleCategory category) {
        switch (category) {                 // pick prefix by category
            case ECONOMY: return "ECO";
            case SUV: return "SUV";
            default: return "LUX";
        }
    }
}

