// Strategy interface: how a rental's cost is computed.
interface VehiclePricingStrategy {
    double calculateCost(Vehicle vehicle, int days, String pickupBranchId, String dropoffBranchId);
}

// Standard pricing: per-category daily rate, discount for long rentals.
class StandardVehiclePricingStrategy implements VehiclePricingStrategy {
    private double dailyRate(VehicleCategory category) {
        switch (category) {               // rate table
            case ECONOMY: return 40.0;
            case SUV: return 70.0;
            default: return 120.0;
        }
    }

    @Override
    public double calculateCost(Vehicle vehicle, int days, String pickupBranchId, String dropoffBranchId) {
        double rate = dailyRate(vehicle.getCategory()); // base per-day rate
        double base = rate * days;                       // total before discount
        if (days >= 7) {                                  // long-duration discount
            base = base * 0.9;                             // 10 percent off
        }
        return base; // final base cost (fees added separately)
    }
}

// A single rental request end-to-end.
class Reservation {
    private final String reservationId;   // unique id
    private final String customerId;      // who booked it
    private final String vehicleId;       // which vehicle
    private final String pickupBranchId;  // where it starts
    private final String dropoffBranchId; // where it ends
    private final int plannedDays;        // how long it was planned for
    private String status;                // CONFIRMED, RETURNED

    public Reservation(String reservationId, String customerId, String vehicleId,
                        String pickupBranchId, String dropoffBranchId, int plannedDays) {
        this.reservationId = reservationId;   // store id
        this.customerId = customerId;         // store customer
        this.vehicleId = vehicleId;           // store vehicle
        this.pickupBranchId = pickupBranchId; // store pickup branch
        this.dropoffBranchId = dropoffBranchId; // store dropoff branch
        this.plannedDays = plannedDays;       // store planned duration
        this.status = "CONFIRMED";            // starts confirmed
    }

    public String getReservationId() { return reservationId; }     // id getter
    public String getCustomerId() { return customerId; }           // customer getter
    public String getVehicleId() { return vehicleId; }             // vehicle getter
    public String getPickupBranchId() { return pickupBranchId; }   // pickup getter
    public String getDropoffBranchId() { return dropoffBranchId; } // dropoff getter
    public int getPlannedDays() { return plannedDays; }            // planned days getter
    public String getStatus() { return status; }                  // status getter
    public void setStatus(String status) { this.status = status; } // status setter
}

// The final computed charge for a completed rental.
class Bill {
    private final double baseCost;  // rate times days (minus discount)
    private final double oneWayFee; // charged if pickup != dropoff branch
    private final double lateFee;   // charged if returned late

    public Bill(double baseCost, double oneWayFee, double lateFee) {
        this.baseCost = baseCost;   // store base
        this.oneWayFee = oneWayFee; // store one-way fee
        this.lateFee = lateFee;     // store late fee
    }

    public double getTotal() { return baseCost + oneWayFee + lateFee; } // sum of all charges
    public double getBaseCost() { return baseCost; }   // base getter
    public double getOneWayFee() { return oneWayFee; } // one-way getter
    public double getLateFee() { return lateFee; }     // late getter
}

