// Observer interface: reacts to rental lifecycle events.
interface RentalObserver {
    void onReservationConfirmed(Reservation reservation);          // reservation created
    void onReservationRejected(String customerId, String reason);  // reservation refused
    void onVehiclePickedUp(Reservation reservation);                // customer took the vehicle
    void onVehicleReturned(Reservation reservation, Bill bill);     // customer returned it
}

// Simple observer that prints events to the console.
class ConsoleRentalObserver implements RentalObserver {
    @Override
    public void onReservationConfirmed(Reservation reservation) {
        System.out.println("Reservation " + reservation.getReservationId() + " confirmed for customer " + reservation.getCustomerId());
    }

    @Override
    public void onReservationRejected(String customerId, String reason) {
        System.out.println("Reservation rejected for customer " + customerId + ": " + reason);
    }

    @Override
    public void onVehiclePickedUp(Reservation reservation) {
        System.out.println("Vehicle " + reservation.getVehicleId() + " picked up by " + reservation.getCustomerId());
    }

    @Override
    public void onVehicleReturned(Reservation reservation, Bill bill) {
        System.out.println("Vehicle " + reservation.getVehicleId() + " returned by " + reservation.getCustomerId() + ", total: " + bill.getTotal());
    }
}

// Custom exceptions for the realistic failure modes.
class VehicleNotAvailableException extends RuntimeException {
    public VehicleNotAvailableException(String msg) { super(msg); }
}
class InvalidReservationException extends RuntimeException {
    public InvalidReservationException(String msg) { super(msg); }
}
class VehicleNotRentedException extends RuntimeException {
    public VehicleNotRentedException(String msg) { super(msg); }
}

// The core orchestrator tying every piece together.
class CarRentalService {
    private final java.util.Map<String, Vehicle> vehicles = new java.util.HashMap<>();       // vehicleId -> Vehicle
    private final java.util.Map<String, Reservation> reservations = new java.util.HashMap<>(); // reservationId -> Reservation
    private final VehiclePricingStrategy pricingStrategy;   // pluggable pricing
    private final java.util.List<RentalObserver> observers = new java.util.ArrayList<>(); // listeners
    private int reservationCounter = 0; // simple id generator

    public CarRentalService(VehiclePricingStrategy pricingStrategy) {
        this.pricingStrategy = pricingStrategy; // store chosen strategy
    }

    public void addVehicle(Vehicle vehicle) { vehicles.put(vehicle.getVehicleId(), vehicle); } // register a vehicle
    public void addObserver(RentalObserver observer) { observers.add(observer); }               // register a listener

    // Finds a free vehicle of the given category at the pickup branch, or throws.
    public synchronized Reservation reserveVehicle(String customerId, VehicleCategory category,
                                                     String pickupBranchId, String dropoffBranchId, int plannedDays) {
        if (plannedDays <= 0) {                                    // guard against bad input
            throw new InvalidReservationException("plannedDays must be positive");
        }
        Vehicle found = null;                                      // will hold the matching vehicle
        for (Vehicle v : vehicles.values()) {                       // scan all vehicles
            if (v.getCategory() == category
                    && v.getCurrentBranchId().equals(pickupBranchId)
                    && v.isAvailable()) {                            // match category, branch, and free
                found = v;                                           // remember it
                break;                                                // stop at first match
            }
        }
        if (found == null) {                                        // nothing matched
            for (RentalObserver obs : observers) obs.onReservationRejected(customerId, "Vehicle not available"); // notify
            throw new VehicleNotAvailableException("No " + category + " vehicle available at " + pickupBranchId);
        }
        found.setStatus(VehicleStatus.RESERVED);                    // claim the vehicle
        reservationCounter++;                                        // bump id counter
        String reservationId = "RES-" + reservationCounter;          // build id
        Reservation reservation = new Reservation(reservationId, customerId, found.getVehicleId(),
                pickupBranchId, dropoffBranchId, plannedDays);        // build reservation
        reservations.put(reservationId, reservation);                // store it
        for (RentalObserver obs : observers) obs.onReservationConfirmed(reservation); // notify
        return reservation; // hand back to caller
    }

    // Marks a reserved vehicle as picked up (RENTED).
    public void pickUp(String reservationId) {
        Reservation reservation = reservations.get(reservationId);   // look up reservation
        if (reservation == null) throw new InvalidReservationException("Unknown reservation: " + reservationId);
        Vehicle vehicle = vehicles.get(reservation.getVehicleId());   // look up vehicle
        vehicle.setStatus(VehicleStatus.RENTED);                      // mark rented
        for (RentalObserver obs : observers) obs.onVehiclePickedUp(reservation); // notify
    }

    // Computes the bill, frees the vehicle at the dropoff branch, and notifies observers.
    public Bill returnVehicle(String reservationId, int actualDays) {
        Reservation reservation = reservations.get(reservationId);    // look up reservation
        if (reservation == null) throw new InvalidReservationException("Unknown reservation: " + reservationId);
        Vehicle vehicle = vehicles.get(reservation.getVehicleId());    // look up vehicle
        if (vehicle.getStatus() != VehicleStatus.RENTED) {              // must currently be rented
            throw new VehicleNotRentedException("Vehicle " + vehicle.getVehicleId() + " is not currently rented");
        }
        double base = pricingStrategy.calculateCost(vehicle, reservation.getPlannedDays(),
                reservation.getPickupBranchId(), reservation.getDropoffBranchId()); // base cost
        double oneWayFee = reservation.getPickupBranchId().equals(reservation.getDropoffBranchId()) ? 0.0 : 25.0; // flat fee if branches differ
        int lateDays = Math.max(0, actualDays-reservation.getPlannedDays());        // days beyond plan
        double dailyRate = base / Math.max(1, reservation.getPlannedDays());        // approximate per-day rate for late fee
        double lateFee = lateDays * dailyRate * 1.5;                                  // 1.5x rate per late day
        Bill bill = new Bill(base, oneWayFee, lateFee);                              // build bill
        vehicle.setStatus(VehicleStatus.AVAILABLE);                                   // free the vehicle
        vehicle.setCurrentBranchId(reservation.getDropoffBranchId());                 // it now lives at the dropoff branch
        reservation.setStatus("RETURNED");                                            // mark reservation done
        for (RentalObserver obs : observers) obs.onVehicleReturned(reservation, bill); // notify
        return bill; // hand back to caller
    }
}

