using namespace std;

// Observer interface: reacts to rental lifecycle events.
class RentalObserver {
public:
    virtual void onReservationConfirmed(const Reservation& reservation) = 0;
    virtual void onReservationRejected(const string& customerId, const string& reason) = 0;
    virtual void onVehiclePickedUp(const Reservation& reservation) = 0;
    virtual void onVehicleReturned(const Reservation& reservation, const Bill& bill) = 0;
    virtual ~RentalObserver() {}
};

// Simple observer that prints events to the console.
class ConsoleRentalObserver : public RentalObserver {
public:
    void onReservationConfirmed(const Reservation& reservation) override {
        cout << "Reservation " << reservation.reservationId << " confirmed for customer " << reservation.customerId << endl;
    }
    void onReservationRejected(const string& customerId, const string& reason) override {
        cout << "Reservation rejected for customer " << customerId << ": " << reason << endl;
    }
    void onVehiclePickedUp(const Reservation& reservation) override {
        cout << "Vehicle " << reservation.vehicleId << " picked up by " << reservation.customerId << endl;
    }
    void onVehicleReturned(const Reservation& reservation, const Bill& bill) override {
        cout << "Vehicle " << reservation.vehicleId << " returned by " << reservation.customerId << ", total: " << bill.getTotal() << endl;
    }
};

// Custom exceptions for the realistic failure modes.
class VehicleNotAvailableException : public runtime_error {
public: VehicleNotAvailableException(const string& msg) : runtime_error(msg) {}
};
class InvalidReservationException : public runtime_error {
public: InvalidReservationException(const string& msg) : runtime_error(msg) {}
};
class VehicleNotRentedException : public runtime_error {
public: VehicleNotRentedException(const string& msg) : runtime_error(msg) {}
};

// The core orchestrator tying every piece together.
class CarRentalService {
    map<string, Vehicle> vehicles;             // vehicleId -> Vehicle
    map<string, Reservation> reservations;     // reservationId -> Reservation
    shared_ptr<VehiclePricingStrategy> pricingStrategy; // pluggable pricing
    vector<shared_ptr<RentalObserver>> observers;        // listeners
    int reservationCounter = 0;                 // simple id generator

public:
    CarRentalService(shared_ptr<VehiclePricingStrategy> strategy) : pricingStrategy(strategy) {}
    // constructor stores the chosen pricing strategy

    void addVehicle(Vehicle vehicle) { vehicles.insert({vehicle.vehicleId, vehicle}); } // register a vehicle
    void addObserver(shared_ptr<RentalObserver> observer) { observers.push_back(observer); } // register a listener

    Reservation reserveVehicle(string customerId, VehicleCategory category,
                                string pickupBranchId, string dropoffBranchId, int plannedDays) {
        if (plannedDays <= 0) {                        // guard against bad input
            throw InvalidReservationException("plannedDays must be positive");
        }
        Vehicle* found = nullptr;                       // will point at the matching vehicle
        for (auto& entry : vehicles) {                   // scan all vehicles
            Vehicle& v = entry.second;
            if (v.category == category && v.currentBranchId == pickupBranchId && v.isAvailable()) {
                found = &v;                                // remember it
                break;                                       // stop at first match
            }
        }
        if (found == nullptr) {                          // nothing matched
            for (auto& obs : observers) obs->onReservationRejected(customerId, "Vehicle not available"); // notify
            throw VehicleNotAvailableException("No vehicle available at " + pickupBranchId);
        }
        found->status = VehicleStatus::RESERVED;          // claim the vehicle
        reservationCounter++;                              // bump id counter
        string reservationId = "RES-" + to_string(reservationCounter); // build id
        Reservation reservation(reservationId, customerId, found->vehicleId,
                                 pickupBranchId, dropoffBranchId, plannedDays); // build reservation
        reservations.insert({reservationId, reservation}); // store it
        for (auto& obs : observers) obs->onReservationConfirmed(reservation); // notify
        return reservation; // hand back to caller
    }

    void pickUp(string reservationId) {
        auto it = reservations.find(reservationId);        // look up reservation
        if (it == reservations.end()) throw InvalidReservationException("Unknown reservation: " + reservationId);
        Vehicle& vehicle = vehicles.at(it->second.vehicleId); // look up vehicle
        vehicle.status = VehicleStatus::RENTED;              // mark rented
        for (auto& obs : observers) obs->onVehiclePickedUp(it->second); // notify
    }

    Bill returnVehicle(string reservationId, int actualDays) {
        auto it = reservations.find(reservationId);         // look up reservation
        if (it == reservations.end()) throw InvalidReservationException("Unknown reservation: " + reservationId);
        Reservation& reservation = it->second;
        Vehicle& vehicle = vehicles.at(reservation.vehicleId); // look up vehicle
        if (vehicle.status != VehicleStatus::RENTED) {          // must currently be rented
            throw VehicleNotRentedException("Vehicle " + vehicle.vehicleId + " is not currently rented");
        }
        double base = pricingStrategy->calculateCost(vehicle, reservation.plannedDays,
                reservation.pickupBranchId, reservation.dropoffBranchId); // base cost
        double oneWayFee = (reservation.pickupBranchId == reservation.dropoffBranchId) ? 0.0 : 25.0; // flat fee if branches differ
        int lateDays = max(0, actualDays-reservation.plannedDays);          // days beyond plan
        double dailyRate = base / max(1, reservation.plannedDays);           // approximate per-day rate for late fee
        double lateFee = lateDays * dailyRate * 1.5;                         // 1.5x rate per late day
        Bill bill(base, oneWayFee, lateFee);                                  // build bill
        vehicle.status = VehicleStatus::AVAILABLE;                            // free the vehicle
        vehicle.currentBranchId = reservation.dropoffBranchId;                // it now lives at the dropoff branch
        reservation.status = "RETURNED";                                      // mark reservation done
        for (auto& obs : observers) obs->onVehicleReturned(reservation, bill); // notify
        return bill; // hand back to caller
    }
};

