class Bill {
    private final double baseCost;
    private final double oneWayFee;
    private final double lateFee;

    public Bill(double baseCost, double oneWayFee, double lateFee) {
        this.baseCost = baseCost;
        this.oneWayFee = oneWayFee;
        this.lateFee = lateFee;
    }

    public double getTotal() { return baseCost + oneWayFee + lateFee; }
}

interface RentalObserver {
    void onReservationConfirmed(Reservation reservation);
    void onReservationRejected(String customerId, String reason);
    void onVehiclePickedUp(Reservation reservation);
    void onVehicleReturned(Reservation reservation, Bill bill);
}

class ConsoleRentalObserver implements RentalObserver {
    @Override
    public void onReservationConfirmed(Reservation reservation) {
        System.out.println("Reservation " + reservation.getReservationId() + " confirmed for customer " + reservation.getCustomerId());
    }

    @Override
    public void onReservationRejected(String customerId, String reason) {
        System.out.println("Reservation rejected for customer " + customerId + ": " + reason);
    }

    @Override
    public void onVehiclePickedUp(Reservation reservation) {
        System.out.println("Vehicle " + reservation.getVehicleId() + " picked up by " + reservation.getCustomerId());
    }

    @Override
    public void onVehicleReturned(Reservation reservation, Bill bill) {
        System.out.println("Vehicle " + reservation.getVehicleId() + " returned by " + reservation.getCustomerId() + ", total: " + bill.getTotal());
    }
}

class VehicleNotAvailableException extends RuntimeException {
    public VehicleNotAvailableException(String msg) { super(msg); }
}
class InvalidReservationException extends RuntimeException {
    public InvalidReservationException(String msg) { super(msg); }
}
class VehicleNotRentedException extends RuntimeException {
    public VehicleNotRentedException(String msg) { super(msg); }
}

class CarRentalService {
    private final Map<String, Vehicle> vehicles = new HashMap<>();
    private final Map<String, Reservation> reservations = new HashMap<>();
    private final VehiclePricingStrategy pricingStrategy;
    private final List<RentalObserver> observers = new ArrayList<>();
    private int reservationCounter = 0;

    public CarRentalService(VehiclePricingStrategy pricingStrategy) {
        this.pricingStrategy = pricingStrategy;
    }

    public void addVehicle(Vehicle vehicle) { vehicles.put(vehicle.getVehicleId(), vehicle); }
    public void addObserver(RentalObserver observer) { observers.add(observer); }

    public synchronized Reservation reserveVehicle(String customerId, VehicleCategory category,
                                                     String pickupBranchId, String dropoffBranchId, int plannedDays) {
        if (plannedDays <= 0) {
            throw new InvalidReservationException("plannedDays must be positive");
        }
        Vehicle found = null;
        for (Vehicle v : vehicles.values()) {
            if (v.getCategory() == category && v.getCurrentBranchId().equals(pickupBranchId) && v.isAvailable()) {
                found = v;
                break;
            }
        }
        if (found == null) {
            for (RentalObserver obs : observers) obs.onReservationRejected(customerId, "Vehicle not available");
            throw new VehicleNotAvailableException("No " + category + " vehicle available at " + pickupBranchId);
        }
        found.setStatus(VehicleStatus.RESERVED);
        reservationCounter++;
        String reservationId = "RES-" + reservationCounter;
        Reservation reservation = new Reservation(reservationId, customerId, found.getVehicleId(),
                pickupBranchId, dropoffBranchId, plannedDays);
        reservations.put(reservationId, reservation);
        for (RentalObserver obs : observers) obs.onReservationConfirmed(reservation);
        return reservation;
    }

    public void pickUp(String reservationId) {
        Reservation reservation = reservations.get(reservationId);
        if (reservation == null) throw new InvalidReservationException("Unknown reservation: " + reservationId);
        Vehicle vehicle = vehicles.get(reservation.getVehicleId());
        vehicle.setStatus(VehicleStatus.RENTED);
        for (RentalObserver obs : observers) obs.onVehiclePickedUp(reservation);
    }

    public Bill returnVehicle(String reservationId, int actualDays) {
        Reservation reservation = reservations.get(reservationId);
        if (reservation == null) throw new InvalidReservationException("Unknown reservation: " + reservationId);
        Vehicle vehicle = vehicles.get(reservation.getVehicleId());
        if (vehicle.getStatus() != VehicleStatus.RENTED) {
            throw new VehicleNotRentedException("Vehicle " + vehicle.getVehicleId() + " is not currently rented");
        }
        double base = pricingStrategy.calculateCost(vehicle, reservation.getPlannedDays(),
                reservation.getPickupBranchId(), reservation.getDropoffBranchId());
        double oneWayFee = reservation.getPickupBranchId().equals(reservation.getDropoffBranchId()) ? 0.0 : 25.0;
        int lateDays = Math.max(0, actualDays-reservation.getPlannedDays());
        double dailyRate = base / Math.max(1, reservation.getPlannedDays());
        double lateFee = lateDays * dailyRate * 1.5;
        Bill bill = new Bill(base, oneWayFee, lateFee);
        vehicle.setStatus(VehicleStatus.AVAILABLE);
        vehicle.setCurrentBranchId(reservation.getDropoffBranchId());
        reservation.setStatus("RETURNED");
        for (RentalObserver obs : observers) obs.onVehicleReturned(reservation, bill);
        return bill;
    }
}

