using namespace std;

enum class VehicleCategory { ECONOMY, SUV, LUXURY };
enum class VehicleStatus { AVAILABLE, RESERVED, RENTED };

string categoryName(VehicleCategory c) {
    if (c == VehicleCategory::ECONOMY) return "ECONOMY";
    if (c == VehicleCategory::SUV) return "SUV";
    return "LUXURY";
}

class Vehicle {
public:
    string vehicleId;
    VehicleCategory category;
    string currentBranchId;
    VehicleStatus status;

    Vehicle() {}
    Vehicle(string id, VehicleCategory cat, string branchId)
        : vehicleId(id), category(cat), currentBranchId(branchId), status(VehicleStatus::AVAILABLE) {}

    bool isAvailable() const { return status == VehicleStatus::AVAILABLE; }
};

class VehicleFactory {
    map<string, int> counters;

    string prefixFor(VehicleCategory category) {
        if (category == VehicleCategory::ECONOMY) return "ECO";
        if (category == VehicleCategory::SUV) return "SUV";
        return "LUX";
    }

public:
    vector<Vehicle> createVehicles(string branchId, VehicleCategory category, int count) {
        string prefix = prefixFor(category);
        vector<Vehicle> created;
        for (int i = 0; i < count; i++) {
            int n = counters[prefix] + 1;
            counters[prefix] = n;
            created.push_back(Vehicle(prefix + to_string(n), category, branchId));
        }
        return created;
    }
};

class Reservation {
public:
    string reservationId;
    string customerId;
    string vehicleId;
    string pickupBranchId;
    string dropoffBranchId;
    int plannedDays;
    string status;

    Reservation() {}
    Reservation(string resId, string custId, string vehId,
                string pickup, string dropoff, int days)
        : reservationId(resId), customerId(custId), vehicleId(vehId),
          pickupBranchId(pickup), dropoffBranchId(dropoff), plannedDays(days), status("CONFIRMED") {}
};

class Bill {
public:
    double baseCost;
    double oneWayFee;
    double lateFee;

    Bill() : baseCost(0), oneWayFee(0), lateFee(0) {}
    Bill(double base, double oneWay, double late) : baseCost(base), oneWayFee(oneWay), lateFee(late) {}

    double getTotal() const { return baseCost + oneWayFee + lateFee; }
};

class VehiclePricingStrategy {
public:
    virtual double calculateCost(const Vehicle& vehicle, int days,
                                  const string& pickupBranchId, const string& dropoffBranchId) = 0;
    virtual ~VehiclePricingStrategy() {}
};

class StandardVehiclePricingStrategy : public VehiclePricingStrategy {
    double dailyRate(VehicleCategory category) {
        if (category == VehicleCategory::ECONOMY) return 40.0;
        if (category == VehicleCategory::SUV) return 70.0;
        return 120.0;
    }

public:
    double calculateCost(const Vehicle& vehicle, int days,
                          const string& pickupBranchId, const string& dropoffBranchId) override {
        double rate = dailyRate(vehicle.category);
        double base = rate * days;
        if (days >= 7) { base = base * 0.9; }
        return base;
    }
};

class RentalObserver {
public:
    virtual void onReservationConfirmed(const Reservation& reservation) = 0;
    virtual void onReservationRejected(const string& customerId, const string& reason) = 0;
    virtual void onVehiclePickedUp(const Reservation& reservation) = 0;
    virtual void onVehicleReturned(const Reservation& reservation, const Bill& bill) = 0;
    virtual ~RentalObserver() {}
};

class ConsoleRentalObserver : public RentalObserver {
