class VehicleNotAvailableException : public runtime_error {
public: VehicleNotAvailableException(const string& msg) : runtime_error(msg) {}
};
class InvalidReservationException : public runtime_error {
public: InvalidReservationException(const string& msg) : runtime_error(msg) {}
};
class VehicleNotRentedException : public runtime_error {
public: VehicleNotRentedException(const string& msg) : runtime_error(msg) {}
};

class CarRentalService {
    map<string, Vehicle> vehicles;
    map<string, Reservation> reservations;
    shared_ptr<VehiclePricingStrategy> pricingStrategy;
    vector<shared_ptr<RentalObserver>> observers;
    int reservationCounter = 0;

public:
    CarRentalService(shared_ptr<VehiclePricingStrategy> strategy) : pricingStrategy(strategy) {}

    void addVehicle(Vehicle vehicle) { vehicles.insert({vehicle.vehicleId, vehicle}); }
    void addObserver(shared_ptr<RentalObserver> observer) { observers.push_back(observer); }

    Reservation reserveVehicle(string customerId, VehicleCategory category,
                                string pickupBranchId, string dropoffBranchId, int plannedDays) {
        if (plannedDays <= 0) {
            throw InvalidReservationException("plannedDays must be positive");
        }
        Vehicle* found = nullptr;
        for (auto& entry : vehicles) {
            Vehicle& v = entry.second;
            if (v.category == category && v.currentBranchId == pickupBranchId && v.isAvailable()) {
                found = &v;
                break;
            }
        }
        if (found == nullptr) {
            for (auto& obs : observers) obs->onReservationRejected(customerId, "Vehicle not available");
            throw VehicleNotAvailableException("No " + categoryName(category) + " vehicle available at " + pickupBranchId);
        }
        found->status = VehicleStatus::RESERVED;
        reservationCounter++;
        string reservationId = "RES-" + to_string(reservationCounter);
        Reservation reservation(reservationId, customerId, found->vehicleId,
                                 pickupBranchId, dropoffBranchId, plannedDays);
        reservations.insert({reservationId, reservation});
        for (auto& obs : observers) obs->onReservationConfirmed(reservation);
        return reservation;
    }

    void pickUp(string reservationId) {
        auto it = reservations.find(reservationId);
        if (it == reservations.end()) throw InvalidReservationException("Unknown reservation: " + reservationId);
        Vehicle& vehicle = vehicles.at(it->second.vehicleId);
        vehicle.status = VehicleStatus::RENTED;
        for (auto& obs : observers) obs->onVehiclePickedUp(it->second);
    }

    Bill returnVehicle(string reservationId, int actualDays) {
        auto it = reservations.find(reservationId);
        if (it == reservations.end()) throw InvalidReservationException("Unknown reservation: " + reservationId);
        Reservation& reservation = it->second;
        Vehicle& vehicle = vehicles.at(reservation.vehicleId);
        if (vehicle.status != VehicleStatus::RENTED) {
            throw VehicleNotRentedException("Vehicle " + vehicle.vehicleId + " is not currently rented");
        }
        double base = pricingStrategy->calculateCost(vehicle, reservation.plannedDays,
                reservation.pickupBranchId, reservation.dropoffBranchId);
        double oneWayFee = (reservation.pickupBranchId == reservation.dropoffBranchId) ? 0.0 : 25.0;
        int lateDays = max(0, actualDays-reservation.plannedDays);
        double dailyRate = base / max(1, reservation.plannedDays);
        double lateFee = lateDays * dailyRate * 1.5;
        Bill bill(base, oneWayFee, lateFee);
        vehicle.status = VehicleStatus::AVAILABLE;
        vehicle.currentBranchId = reservation.dropoffBranchId;
        reservation.status = "RETURNED";
        for (auto& obs : observers) obs->onVehicleReturned(reservation, bill);
        return bill;
    }
};

int main() {
    auto service = CarRentalService(make_shared<StandardVehiclePricingStrategy>());
    service.addObserver(make_shared<ConsoleRentalObserver>());

    VehicleFactory factory;
    for (auto& v : factory.createVehicles("BR1", VehicleCategory::ECONOMY, 1)) service.addVehicle(v);
    for (auto& v : factory.createVehicles("BR1", VehicleCategory::SUV, 1)) service.addVehicle(v);
    for (auto& v : factory.createVehicles("BR2", VehicleCategory::LUXURY, 1)) service.addVehicle(v);

    Reservation r1 = service.reserveVehicle("Alice", VehicleCategory::ECONOMY, "BR1", "BR2", 3);
    service.pickUp(r1.reservationId);
