        cout << "Caught expected: " << e.what() << endl;
    }

    Reservation r3 = service.reserveVehicle("Carol", VehicleCategory::SUV, "BR1", "BR1", 2);
    service.pickUp(r3.reservationId);
    service.returnVehicle(r3.reservationId, 3);

    return 0;
